<div class="modal-backdrop" x-show="modal" x-cloak x-transition.opacity.duration.150ms @click.self="closeModal()"><section class="modal-panel" x-show="modal" x-transition.opacity.scale.95.duration.150ms x-ref="modalPanel" @keydown.tab="trap($event)" role="dialog" aria-modal="true" aria-labelledby="modal-title">
<header class="modal-heading"><div><span class="modal-kicker" x-text="modal==='task'?'یک قدم در مسیر هدف':'فضای کار راستا'"></span><h2 id="modal-title" x-text="({task:taskForm.id?'ویرایش تسک':'تسک جدید',project:'یک پروژه تازه',stage:stageId?'ویرایش مرحله':'مرحله جدید',label:labelForm.id?'ویرایش برچسب':'برچسب جدید',goal:'هدف پروژه',member:'افزودن هم‌تیمی'})[modal]"></h2></div><button class="icon-btn" @click="closeModal()" aria-label="بستن فرم" x-html="$icon('X')"></button></header>
<template x-if="modal==='task'"><form class="task-composer todoist-task-modal" @submit.prevent="taskForm.id?autosaveTaskNow():saveTask()">
<div class="task-modal-topbar">
    <div class="task-breadcrumb"><span>#</span><strong x-text="formProject?.name||'پروژه'"></strong><span>/</span><span x-text="selectedProductStage?.title||'بدون مرحله'"></span></div>
    <div class="task-top-actions"><button type="button" class="icon-btn" x-show="taskForm.id" @click="taskNeighbor(-1)" aria-label="تسک قبلی">↑</button><button type="button" class="icon-btn" x-show="taskForm.id" @click="taskNeighbor(1)" aria-label="تسک بعدی">↓</button><div x-data="{open:false}" class="task-more" @click.outside="open=false"><button type="button" class="icon-btn" @click="open=!open" aria-label="گزینه‌های تسک" x-html="$icon('MoreHorizontal')"></button><div class="dropdown-menu task-more-menu" x-show="open" x-transition.opacity.scale.95.duration.150ms><button class="danger-text" x-show="taskForm.id" type="button" @click="removeTask();open=false">حذف تسک</button></div></div><button type="button" class="icon-btn" @click="closeTaskComposer()" aria-label="بستن" x-html="$icon('X')"></button></div>
</div>
<div class="task-modal-grid">
    <main class="task-modal-main">
        <div class="task-title-row"><button type="button" class="completion task-main-completion" :class="{'checked':taskForm.completed_at||taskForm.completed}" @click="toggleTaskForm()" :disabled="!canWrite(formProject)"><span x-show="taskForm.completed_at||taskForm.completed" x-html="$icon('Check')"></span></button><input class="task-title-editor" x-model="taskForm.title" @input="scheduleTaskAutosave()" placeholder="نام تسک" required maxlength="200"></div>
        <div class="task-description-editor"><span>≡</span><textarea x-model="taskForm.description" @input="scheduleTaskAutosave()" placeholder="توضیحات" rows="2" maxlength="10000"></textarea></div>
        <button type="button" class="add-subtask-link" @click="addSubtask()"><span x-html="$icon('Plus')"></span>افزودن زیرتسک</button>
        <div class="task-subtasks" x-show="taskForm.subtasks.length"><template x-for="(s,i) in taskForm.subtasks" :key="s.id||i"><div class="task-subtask-row" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="reorderSubtask(i);autosaveTaskNow()"><span class="subtask-drag" x-html="$icon('GripVertical')"></span><button type="button" class="subtask-completion" :class="{'checked':s.completed}" @click="s.completed=!s.completed;autosaveTaskNow()"><span x-show="s.completed" x-html="$icon('Check')"></span></button><input x-model="s.title" @input="scheduleTaskAutosave()" placeholder="عنوان زیرتسک" maxlength="200"><button type="button" class="icon-btn remove-subtask" @click="taskForm.subtasks.splice(i,1);autosaveTaskNow()" x-html="$icon('X')"></button></div></template></div>
        <div class="task-main-divider"></div>
        <div class="task-comment-composer" x-show="taskForm.id"><span class="avatar comment-avatar"><img x-show="user.avatar_url" :src="user.avatar_url" :alt="user.name"><span x-show="!user.avatar_url" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span></span><div class="comment-pill"><textarea x-model="commentText" placeholder="نظر بنویسید..." rows="1" maxlength="5000"></textarea><label class="comment-attach" aria-label="افزودن پیوست"><input type="file" class="sr-only" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="filesAdded($event.target.files);$event.target.value=''"/><span x-html="$icon('Paperclip')"></span></label><button type="button" class="comment-send" x-show="commentText.trim()" x-transition.opacity.duration.150ms @click="addComment()" x-html="$icon('ArrowUpLeft')"></button></div></div>
        <div class="task-comments" x-show="taskForm.id"><template x-for="c in taskForm.comments" :key="c.id"><div class="comment"><span class="avatar small"><img x-show="c.user?.avatar_url" :src="c.user?.avatar_url" :alt="c.user?.name"><span x-show="!c.user?.avatar_url" :style="`background:${color(c.member_id)}`" x-text="initials(c.user?.name)"></span></span><div class="comment-content"><div><strong x-text="c.user?.name"></strong><small x-text="commentTime(c.created_at)"></small></div><p x-show="!c.editing" x-text="c.body"></p><div x-show="c.editing"><textarea x-model="c.editBody" rows="2"></textarea><div class="button-row"><button class="text-button accent" type="button" @click="editComment(c)">ذخیره</button><button class="text-button" type="button" @click="c.editing=false">لغو</button></div></div><div class="comment-actions" x-show="c.member_id===user.id&&canWrite(formProject)"><button type="button" @click="c.editing=true;c.editBody=c.body">ویرایش</button><button type="button" class="danger-text" @click="deleteComment(c)">حذف</button></div></div></div></template></div>
        <details class="task-history-collapsed" x-show="taskForm.id"><summary><span x-html="$icon('History')"></span><span>تاریخچه</span><span x-text="fa((taskForm.activities||[]).length)"></span></summary><div class="task-history-list"><template x-for="a in taskForm.activities||[]" :key="a.id"><div class="activity-row"><span class="activity-dot"></span><div><p x-text="activityText(a)"></p><small x-text="relativeTime(a.created_at)"></small></div></div></template></div></details>
        <div class="new-task-submit" x-show="!taskForm.id"><button type="submit" class="button primary" :disabled="busy||!taskForm.title?.trim()||!taskForm.member_stage_id">افزودن تسک</button></div>
    </main>
    <aside class="task-details-panel">
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">پروژه</span><button type="button" class="task-detail-value" @click="if(!taskForm.id)open=!open"><span>#</span><span x-text="formProject?.name||'انتخاب پروژه'"></span><span x-show="!taskForm.id" x-html="$icon('Plus')"></span></button><div class="task-side-popover" x-show="open&&!taskForm.id" x-transition.opacity.scale.95.duration.150ms><template x-for="p in projects" :key="p.id"><button type="button" @click="taskForm.project_id=p.id;projectChanged();open=false" x-text="p.name"></button></template></div></div>
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">مرحله من</span><button type="button" class="task-detail-value" @click="open=!open"><span x-text="formMyStages.find(s=>s.id==taskForm.member_stage_id)?.title||'انتخاب مرحله'"></span><span x-html="$icon('Plus')"></span></button><div class="task-product-stage-readonly" x-show="selectedProductStage"><span>مرحله محصول</span><strong x-text="selectedProductStage?.title"></strong></div><div class="task-side-popover" x-show="open" x-transition.opacity.scale.95.duration.150ms><template x-for="s in formMyStages" :key="s.id"><button type="button" @click="taskForm.member_stage_id=s.id;memberStageChanged();open=false" x-text="s.title"></button></template><button type="button" class="accent" @click="startInlineStage();open=false"><span x-html="$icon('Plus')"></span>ساخت مرحله من</button></div></div>
        <div class="inline-stage-side" x-show="inlineStage"><label>مرحله محصول مادر<select x-model.number="inlineStageForm.product_stage_id"><option value="">انتخاب مرحله محصول</option><template x-for="s in formProject?.stages||[]" :key="s.id"><option :value="s.id" x-text="s.title"></option></template></select></label><input x-model="inlineStageForm.title" placeholder="عنوان مرحله من"><div class="button-row"><button type="button" class="button primary small-button" @click="createInlineStage()">ساخت</button><button type="button" class="text-button" @click="inlineStage=false">لغو</button></div></div>
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">مسئول</span><button type="button" class="task-detail-value" @click="open=!open"><span class="avatar detail-avatar"><img x-show="member(taskForm.owner_id)?.avatar_url" :src="member(taskForm.owner_id)?.avatar_url"><span x-show="!member(taskForm.owner_id)?.avatar_url" :style="`background:${color(taskForm.owner_id)}`" x-text="initials(member(taskForm.owner_id)?.name)"></span></span><span x-text="member(taskForm.owner_id)?.name||'انتخاب مسئول'"></span><span x-html="$icon('Plus')"></span></button><div class="task-side-popover" x-show="open" x-transition.opacity.scale.95.duration.150ms><template x-for="m in formProject?.members||[]" :key="m.id"><button type="button" @click="taskForm.owner_id=m.id;ownerChanged();open=false"><span class="avatar detail-avatar"><img x-show="m.avatar_url" :src="m.avatar_url"><span x-show="!m.avatar_url" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></span><span x-text="m.name"></span></button></template></div></div>
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">همراهان</span><button type="button" class="task-detail-value" @click="open=!open"><span x-text="taskForm.members.length?fa(taskForm.members.length)+' نفر':'افزودن همراه'"></span><span x-html="$icon('Plus')"></span></button><div class="task-side-popover checklist-popover" x-show="open" x-transition.opacity.scale.95.duration.150ms><template x-for="m in formProject?.members||[]" :key="m.id"><label><input type="checkbox" :value="m.id" x-model.number="taskForm.members" @change="autosaveTaskNow()"><span class="avatar detail-avatar"><img x-show="m.avatar_url" :src="m.avatar_url"><span x-show="!m.avatar_url" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></span><span x-text="m.name"></span></label></template></div></div>
        <div class="task-detail-row" x-effect="taskForm.start_date; if(taskForm.id) scheduleTaskAutosave()"><span class="task-detail-label">تاریخ شروع</span><div class="task-detail-date"><x-date-picker model="taskForm.start_date" label="تاریخ شروع" /></div></div>
        <div class="task-detail-row" x-effect="taskForm.due_date; if(taskForm.id) scheduleTaskAutosave()"><span class="task-detail-label">مهلت</span><div class="task-detail-date"><x-date-picker model="taskForm.due_date" label="مهلت" /></div></div>
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">برچسب‌ها</span><button type="button" class="task-detail-value" @click="open=!open"><span x-text="taskForm.labels.length?fa(taskForm.labels.length)+' برچسب':'افزودن برچسب'"></span><span x-html="$icon('Plus')"></span></button><div class="task-side-popover checklist-popover labels-popover" x-show="open" x-transition.opacity.scale.95.duration.150ms><input x-model="labelQuery" placeholder="جست‌وجوی برچسب"><template x-for="l in formLabels" :key="l.id"><label><input type="checkbox" :value="l.id" x-model.number="taskForm.labels" @change="autosaveTaskNow()"><span x-html="$icon('Tags')"></span><span x-text="l.name"></span></label></template><button type="button" class="accent" x-show="labelQuery&&!formLabels.some(l=>l.name===labelQuery)" @click="quickLabel()"><span x-html="$icon('Plus')"></span><span x-text="'ساخت «'+labelQuery+'»'"></span></button></div></div>
        <div class="task-detail-row" x-data="{open:false}" @click.outside="open=false"><span class="task-detail-label">پیوست‌ها</span><button type="button" class="task-detail-value" @click="open=!open"><span x-text="fa((taskForm.attachments||[]).length+pendingFiles.length)+' فایل'"></span><span x-html="$icon('Plus')"></span></button><div class="task-side-popover attachments-popover" x-show="open" x-transition.opacity.scale.95.duration.150ms><label class="attachment-add"><input type="file" class="sr-only" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="filesAdded($event.target.files);$event.target.value=''"/><span x-html="$icon('Paperclip')"></span>افزودن فایل</label><template x-for="a in taskForm.attachments||[]" :key="a.id"><div class="side-attachment"><a :href="'/attachments/'+a.id" x-text="a.original_name"></a><button type="button" class="icon-btn" x-show="a.member_id===user.id" @click="deleteAttachment(a)" x-html="$icon('X')"></button></div></template><template x-for="(f,i) in pendingFiles" :key="i"><div class="side-attachment"><span x-text="f.name"></span><button type="button" class="icon-btn" @click="pendingFiles.splice(i,1)" x-html="$icon('X')"></button></div></template></div></div>
    </aside>
</div>
</form></template>
<template x-if="modal==='project'"><form @submit.prevent="projectStep<3?nextStep():saveProject()"><div class="wizard-steps"><template x-for="(title,i) in ['اطلاعات پروژه','هدف پروژه','مراحل مسیر']" :key="i"><div :class="{'current':projectStep===i+1,'done':projectStep>i+1}"><span x-text="projectStep>i+1?'✓':fa(i+1)"></span><strong x-text="title"></strong></div></template></div><div class="modal-body"><div x-show="projectStep===1"><div class="form-intro"><h3>چه چیزی می‌خواهید بسازید؟</h3><p>با یک نام و توضیح کوتاه، به پروژه‌تان هویت بدهید.</p></div><label>رنگ پروژه<input type="color" x-model="projectForm.color"></label><label>نام پروژه<input x-model="projectForm.name" placeholder="نام پروژه شما" maxlength="150"><small class="field-error" x-text="err('name')"></small></label><label>توضیح کوتاه<textarea x-model="projectForm.description" placeholder="این پروژه درباره چیست؟" rows="3"></textarea></label></div><div x-show="projectStep===2"><div class="helper-box"><span x-html="$icon('Target')"></span><p>ابتدا هدف پروژه را مشخص کنید. مراحل پروژه، مسیر رسیدن به این هدف خواهند بود.</p></div><label>عنوان هدف<input x-model="projectForm.goal.title" placeholder="می‌خواهیم به چه نتیجه‌ای برسیم؟"><small class="field-error" x-text="err('goal.title')"></small></label><label>توضیح هدف<textarea x-model="projectForm.goal.description" rows="2" placeholder="هدف را کمی بیشتر توضیح دهید..."></textarea></label><label>معیار موفقیت<textarea x-model="projectForm.goal.success_criterion" rows="2" placeholder="از کجا بفهمیم به هدف رسیده‌ایم؟"></textarea><small class="field-error" x-text="err('goal.success_criterion')"></small></label><div class="form-grid"><label>تاریخ شروع<x-date-picker model="projectForm.goal.start_date" /><small class="field-error" x-text="err('goal.start_date')"></small></label><label>تاریخ هدف<x-date-picker model="projectForm.goal.target_date" /><small class="field-error" x-text="err('goal.target_date')"></small></label></div></div><div x-show="projectStep===3"><div class="form-intro"><h3>مسیر رسیدن به هدف را بسازید</h3><p>مرحله‌ها را بکشید و به ترتیب دلخواه بچینید.</p></div><template x-for="(s,i) in projectForm.stages" :key="i"><div class="wizard-stage" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="dropWizard(i)"><div class="wizard-stage-title"><span x-html="$icon('GripVertical')"></span><span class="step-number" x-text="fa(i+1)"></span><input x-model="s.title" placeholder="نام مرحله"><button type="button" class="icon-btn" @click="moveWizard(i,-1)" aria-label="مرحله قبل" x-html="$icon('ChevronRight')"></button><button type="button" class="icon-btn" @click="projectForm.stages.splice(i,1)" aria-label="حذف مرحله" x-html="$icon('Trash2')"></button></div><input x-model="s.description" placeholder="توضیح کوتاه (اختیاری)"><div class="form-grid"><label>شروع<x-date-picker model="s.start_date" /></label><label>پایان<x-date-picker model="s.end_date" /></label></div><small class="field-error" x-text="Object.keys(errors).filter(k=>k.startsWith('stages.'+i+'.')).map(k=>err(k)).join(' ')"></small></div></template><button type="button" class="button full-width dashed" @click="projectForm.stages.push({title:'',description:'',start_date:projectForm.goal.start_date,end_date:projectForm.goal.target_date})"><span x-html="$icon('Plus')"></span>افزودن مرحله</button><small class="field-error" x-text="err('stages')"></small></div></div><footer class="modal-footer"><span class="muted" x-text="'مرحله '+fa(projectStep)+' از ۳'"></span><div class="button-row"><button type="button" class="button" @click="projectStep>1?projectStep--:closeModal()" x-text="projectStep>1?'قبلی':'انصراف'"></button><button class="button primary" type="submit" :disabled="busy" x-text="busy?'در حال ساخت...':projectStep===3?'ساخت پروژه':'ادامه'"></button></div></footer></form></template>
<template x-if="modal==='stage'"><form @submit.prevent="saveStage()"><div class="modal-body"><div class="helper-box" x-show="stageUser"><span x-html="$icon('Users')"></span><p x-text="'مسیر اختصاصی '+stageUser?.name"></p></div><label x-show="stageUser">زیرمجموعه مرحله محصول<select x-model.number="stageForm.product_stage_id" :required="!!stageUser"><option value="">انتخاب مرحله محصول</option><template x-for="s in stageProject?.stages||[]" :key="s.id"><option :value="s.id" x-text="s.title"></option></template></select><small class="field-error" x-text="err('product_stage_id')"></small></label><label>نام مرحله<input x-model="stageForm.title" required maxlength="120"><small class="field-error" x-text="err('title')"></small></label><label>توضیحات<textarea x-model="stageForm.description" rows="3"></textarea></label><div class="form-grid"><label>شروع<x-date-picker model="stageForm.start_date" /><small class="field-error" x-text="err('start_date')"></small></label><label>پایان<x-date-picker model="stageForm.end_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><button type="button" class="text-button danger-text" x-show="stageId&&canWrite(stageProject)" @click="deleteStage({...stageForm,id:stageId,project_id:stageProjectId},stageKind,stageUser)">حذف مرحله</button><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy||!canWrite(stageProject)">ذخیره مرحله</button></div></footer></form></template>
<template x-if="modal==='goal'"><form @submit.prevent="saveGoal()"><div class="modal-body"><label>عنوان هدف<input x-model="goalForm.title" required><small class="field-error" x-text="err('title')"></small></label><label>توضیح هدف<textarea x-model="goalForm.description" rows="3"></textarea></label><label>معیار موفقیت<textarea x-model="goalForm.success_criterion" required rows="3"></textarea><small class="field-error" x-text="err('success_criterion')"></small></label><div class="form-grid"><label>شروع<x-date-picker model="goalForm.start_date" /></label><label>پایان<x-date-picker model="goalForm.target_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره هدف</button></div></footer></form></template>
<template x-if="modal==='label'"><form @submit.prevent="saveLabel()"><div class="modal-body"><label>نام برچسب<input x-model="labelForm.name" required maxlength="60"><small class="field-error" x-text="err('name')"></small></label><label>رنگ<div class="color-picker"><input type="color" x-model="labelForm.color"><template x-for="c in ['#ed8555','#9274be','#568c7b','#527fa9','#bb6073','#9b864f']"><button type="button" :style="`background:${c}`" @click="labelForm.color=c" :aria-label="'انتخاب رنگ '+c" :class="{'chosen':labelForm.color===c}"></button></template></div></label><label>توضیحات (اختیاری)<textarea x-model="labelForm.description" rows="2"></textarea></label><label x-show="!labelForm.id">محدوده برچسب<select x-model.number="labelForm.project_id"><option :value="null">شخصی، در همه پروژه‌ها</option><template x-for="p in projects.filter(p=>canWrite(p))" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select></label></div><footer class="modal-footer"><span class="tag" :style="`--tag-color:${labelForm.color}`" x-text="labelForm.name||'پیش‌نمایش'"></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره برچسب</button></div></footer></form></template>
<template x-if="modal==='member'"><form @submit.prevent="saveMember()"><div class="modal-body"><label>انتخاب هم‌تیمی<select x-model.number="memberForm.member_id" required><option value="">انتخاب عضو</option><template x-for="m in members.filter(m=>!currentProject?.members.some(x=>x.id===m.id))" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select><small class="field-error" x-text="err('member_id')"></small></label><p class="muted">اعضا از بخش «شما کی هستید؟» پروفایل خود را می‌سازند.</p></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy" x-text="busy?'در حال ذخیره...':'افزودن عضو'"></button></div></footer></form></template>
</section></div>